import hashlib, json, re, sys
from pathlib import Path
package, original = map(Path, sys.argv[1:])
try:
    (original / 'planning/SKILL.md').read_text()
except PermissionError:
    denied = True
else:
    raise AssertionError('Original checkout remained readable')
hashes, links = {}, []
for path in package.rglob('*'):
    if not path.is_file():
        continue
    resolved = path.resolve(strict=True)
    assert resolved.is_relative_to(package.resolve()), str(path)
    hashes[str(path.relative_to(package))] = hashlib.sha256(path.read_bytes()).hexdigest()
    if path.suffix == '.md':
        for link in re.findall(r'\]\(([^)]+)\)', path.read_text()):
            if link.startswith(('https://', 'http://', '#')):
                continue
            target = (path.parent / link.split('#')[0]).resolve(strict=True)
            assert target.is_file() and target.is_relative_to(package.resolve()), link
            target.read_text()
            links.append(str(target.relative_to(package)))
assert sorted(links) == ['assets/implementation-plan.md', 'references/work-units.md'], {'links': links, 'hashes': hashes}
print(json.dumps({'originalCheckoutDenied': denied, 'files': hashes, 'resolvedLinks': links}))
